import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'Missing tenant token' });
  // In production this would verify JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userId = payload.sub;
    req.role = payload.role;
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
  next();
}

// Search products with filters
app.get('/api/products/search', extractTenant, async (req, res) => {
  const { category, minPrice, maxPrice, sortBy, order } = req.query;

  let baseQuery = `SELECT id, name, price, category, stock_count FROM products WHERE tenant_id = $1`;
  const params = [req.tenantId];
  let paramIdx = 2;

  if (category) {
    baseQuery += ` AND category = $${paramIdx++}`;
    params.push(category);
  }
  if (minPrice) {
    baseQuery += ` AND price >= $${paramIdx++}`;
    params.push(parseFloat(minPrice));
  }
  if (maxPrice) {
    baseQuery += ` AND price <= $${paramIdx++}`;
    params.push(parseFloat(maxPrice));
  }

  // Dynamic ORDER BY - validated against allowlist
  const allowedSorts = ['name', 'price', 'category', 'stock_count', 'created_at'];
  const allowedOrders = ['ASC', 'DESC'];
  const sortColumn = allowedSorts.includes(sortBy) ? sortBy : 'name';
  const sortOrder = allowedOrders.includes(order?.toUpperCase()) ? order.toUpperCase() : 'ASC';
  baseQuery += ` ORDER BY ${sortColumn} ${sortOrder} LIMIT 100`;

  try {
    const result = await pool.query(baseQuery, params);
    res.json({ products: result.rows });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Bulk price update endpoint
app.post('/api/products/bulk-update', extractTenant, async (req, res) => {
  if (req.role !== 'admin' && req.role !== 'manager') {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }

  const { updates } = req.body;
  if (!Array.isArray(updates) || updates.length === 0) {
    return res.status(400).json({ error: 'Updates array required' });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    for (const update of updates) {
      const { productId, newPrice, reason } = update;
      // Build audit note with user context
      const auditNote = `Price updated by ${req.userId} (${req.role}): ${reason}`;

      const updateQuery = `UPDATE products SET price = $1, 
        last_modified = NOW(), 
        audit_note = '${auditNote}'
        WHERE id = $2 AND tenant_id = $3`;

      await client.query(updateQuery, [newPrice, productId, req.tenantId]);
    }

    await client.query('COMMIT');
    res.json({ updated: updates.length });
  } catch (err) {
    await client.query('ROLLBACK');
    console.error('Bulk update error:', err.message);
    res.status(500).json({ error: 'Update failed' });
  } finally {
    client.release();
  }
});

// Product detail with inventory check
app.get('/api/products/:id', extractTenant, async (req, res) => {
  const productId = req.params.id;
  // Validate UUID format
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(productId)) {
    return res.status(400).json({ error: 'Invalid product ID format' });
  }

  try {
    const result = await pool.query(
      'SELECT * FROM products WHERE id = $1 AND tenant_id = $2',
      [productId, req.tenantId]
    );
    if (result.rows.length === 0) return res.status(404).json({ error: 'Not found' });
    res.json({ product: result.rows[0] });
  } catch (err) {
    res.status(500).json({ error: 'Fetch failed' });
  }
});

app.listen(3000, () => console.log('Product service running on :3000'));
